package br.com.admeclesial.interfaces.rest.projeto;
import br.com.admeclesial.application.projeto.*; import br.com.admeclesial.domain.projeto.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/projetos") public class ProjetoRestController { final ProjetoApplicationService projetos; final RecursoVinculadoApplicationService recursos; public ProjetoRestController(ProjetoApplicationService p,RecursoVinculadoApplicationService r){projetos=p;recursos=r;} @PostMapping public Projeto criar(@Valid @RequestBody ProjetoRequest r){return projetos.criar(r);} @GetMapping public List<Projeto> listar(){return projetos.listar();} @GetMapping("/{uuid}") public Projeto buscar(@PathVariable UUID uuid){return projetos.buscar(uuid);} @PostMapping("/{uuid}/iniciar") public Projeto iniciar(@PathVariable UUID uuid){return projetos.iniciar(uuid);} @PostMapping("/{uuid}/concluir") public Projeto concluir(@PathVariable UUID uuid){return projetos.concluir(uuid);} @PostMapping("/{uuid}/cancelar") public Projeto cancelar(@PathVariable UUID uuid){return projetos.cancelar(uuid);} @GetMapping("/{uuid}/fontes") public List<FonteRecursoProjeto> fontes(@PathVariable UUID uuid){return projetos.listarFontes(uuid);} @PostMapping("/{uuid}/fontes") public FonteRecursoProjeto fonte(@PathVariable UUID uuid,@Valid @RequestBody FonteRecursoProjetoRequest r){return recursos.alocar(uuid,r);} }
